static lstr L1093 = {0, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
