static lstr L1450 = {0, 12563, "// std/internal/asyncio. Sockets for std/net.\012//\012// A Handle is a counted object that holds one descriptor; the last release\012// closes it. A handle whose call failed holds -1. Every call stores its\012// errno value in narra_io_error (0 on success), which Handles.error reads\012// before any other call can run. Nothing here blocks: the waits are the\012// loop's (narra_loop_wait_io in std_async_loop.c), and the emitter calls them\012// itself, so this text needs nothing from the task runtime.\012#include <errno.h>\012#include <fcntl.h>\012#include <limits.h>\012#ifdef _WIN32\012#include <winsock2.h>\012#include <ws2tcpip.h>\012#include <windows.h>\012#else\012#include <arpa/inet.h>\012#include <netinet/in.h>\012#include <sys/socket.h>\012#endif\012\012// Sockets on Windows are Winsock handles that the C runtime cannot read,\012// write or close, and their errors come from WSAGetLastError. The calls below\012// go through these names; elsewhere they are the plain calls. A Winsock handle\012// is a small number, so it fits the int that holds a descriptor, and\012// INVALID_SOCKET becomes -1.\012#ifdef _WIN32\012static int narra_net_errno(void) {\012  switch (WSAGetLastError()) {\012    case WSAEWOULDBLOCK: return EWOULDBLOCK;\012    case WSAEINPROGRESS: return EINPROGRESS;\012    case WSAEINTR: return EINTR;\012    case WSAEBADF: return EBADF;\012    case WSAEACCES: return EACCES;\012    case WSAEINVAL: return EINVAL;\012    case WSAEMFILE: return EMFILE;\012    case WSAENOTSOCK: return ENOTSOCK;\012    case WSAEAFNOSUPPORT: return EAFNOSUPPORT;\012    case WSAEADDRINUSE: return EADDRINUSE;\012    case WSAEADDRNOTAVAIL: return EADDRNOTAVAIL;\012    case WSAENETDOWN: return ENETDOWN;\012    case WSAENETUNREACH: return ENETUNREACH;\012    case WSAECONNABORTED: return ECONNABORTED;\012    case WSAECONNRESET: return ECONNRESET;\012    case WSAESHUTDOWN: return EPIPE;\012    case WSAENOTCONN: return ENOTCONN;\012    case WSAETIMEDOUT: return ETIMEDOUT;\012    case WSAECONNREFUSED: return ECONNREFUSED;\012    case WSAEHOSTUNREACH: return EHOSTUNREACH;\012    case WSAEMSGSIZE: return EMSGSIZE;\012    case WSAEISCONN: return EISCONN;\012    case WSAEALREADY: return EALREADY;\012    default: return EIO;\012  }\012}\012\012static void narra_net_start(void) {\012  static bool started = false;\012  if (started) return;\012  WSADATA data;\012  WSAStartup(MAKEWORD(2, 2), &data);\012  started = true;\012}\012\012static int narra_net_prepare(int descriptor) {\012  u_long nonblocking = 1;\012  if (ioctlsocket((SOCKET)descriptor, FIONBIO, &nonblocking) != 0) return narra_net_errno();\012  SetHandleInformation((HANDLE)(uintptr_t)(SOCKET)descriptor, HANDLE_FLAG_INHERIT, 0);\012  return 0;\012}\012\012#define narra_net_close(descriptor) closesocket((SOCKET)(descriptor))\012#define narra_net_read(descriptor, buffer, length) recv((SOCKET)(descriptor), (buffer), (int)(length), 0)\012#define narra_net_send(descriptor, buffer, length) send((SOCKET)(descriptor), (buffer), (length) > INT_MAX \077 INT_MAX : (int)(length), 0)\012#else\012#define narra_net_errno() errno\012#define narra_net_start()\012#define narra_net_close(descriptor) close(descriptor)\012#define narra_net_read(descriptor, buffer, length) read((descriptor), (buffer), (length))\012#define narra_net_send(descriptor, buffer, length) send((descriptor), (buffer), (length), MSG_NOSIGNAL)\012#endif\012\012typedef struct narra_handle {\012  int64_t rc;\012  int descriptor;\012} narra_handle;\012\012// Not an errno value: the host is not a numeric IPv4 or IPv6 address.\012#define NARRA_IO_BAD_ADDRESS (-2)\012\012static _Thread_local int narra_io_error = 0;\012\012static narra_handle* narra_handle_new(int descriptor) {\012  narra_handle* handle = narra_alloc(sizeof(narra_handle));\012  handle->rc = 1;\012  handle->descriptor = descriptor;\012  return handle;\012}\012\012static void narra_handle_retain(narra_handle* handle) {\012  handle->rc++;\012}\012\012static void narra_handle_release(narra_handle* handle) {\012  if (--handle->rc == 0) {\012    if (handle->descriptor >= 0) narra_net_close(handle->descriptor);\012    narra_free(handle);\012  }\012}\012\012// A failed call: keeps errno and gives a handle with no descriptor.\012static narra_handle* narra_handle_failed(int descriptor, int error) {\012  if (descriptor >= 0) narra_net_close(descriptor);\012  narra_io_error = error;\012  return narra_handle_new(-1);\012}\012\012// Makes the descriptor nonblocking and closed on exec.\012static int narra_handle_prepare(int descriptor) {\012#ifdef _WIN32\012  return narra_net_prepare(descriptor);\012#else\012  int flags = fcntl(descriptor, F_GETFL, 0);\012  if (flags < 0 || fcntl(descriptor, F_SETFL, flags | O_NONBLOCK) < 0) return errno;\012  if (fcntl(descriptor, F_SETFD, FD_CLOEXEC) < 0) return errno;\012  return 0;\012#endif\012}\012\012// Fills address from a numeric host and a port; false when the host is not\012// a numeric address or the port is out of range.\012static bool narra_handle_address(lstr* host, int64_t port, struct sockaddr_storage* address, socklen_t* size) {\012  memset(address, 0, sizeof(*address));\012  if (port < 0 || port > 65535) return false;\012  struct sockaddr_in* ipv4 = (struct sockaddr_in*)address;\012  if (inet_pton(AF_INET, host->data, &ipv4->sin_addr) == 1) {\012    ipv4->sin_family = AF_INET;\012    ipv4->sin_port = htons((uint16_t)port);\012    *size = sizeof(struct sockaddr_in);\012    return true;\012  }\012  struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)address;\012  if (inet_pton(AF_INET6, host->data, &ipv6->sin6_addr) == 1) {\012    ipv6->sin6_family = AF_INET6;\012    ipv6->sin6_port = htons((uint16_t)port);\012    *size = sizeof(struct sockaddr_in6);\012    return true;\012  }\012  return false;\012}\012\012// A new nonblocking stream socket for address, or -1 with narra_io_error set.\012static int narra_handle_socket(struct sockaddr_storage* address) {\012  narra_net_start();\012  int descriptor = (int)socket(address->ss_family, SOCK_STREAM, 0);\012  if (descriptor < 0) {\012    narra_io_error = narra_net_errno();\012    return -1;\012  }\012  int failure = narra_handle_prepare(descriptor);\012  if (failure != 0) {\012    narra_net_close(descriptor);\012    narra_io_error = failure;\012    return -1;\012  }\012  return descriptor;\012}\012\012static narra_handle* narra_handle_listen(lstr* host, int64_t port) {\012  narra_io_error = 0;\012  struct sockaddr_storage address;\012  socklen_t size = 0;\012  if (!narra_handle_address(host, port, &address, &size)) {\012    return narra_handle_failed(-1, NARRA_IO_BAD_ADDRESS);\012  }\012  int descriptor = narra_handle_socket(&address);\012  if (descriptor < 0) return narra_handle_new(-1);\012  // On Windows SO_REUSEADDR would let a second socket take a port in use.\012#ifndef _WIN32\012  int reuse = 1;\012  setsockopt(descriptor, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));\012#endif\012  if (bind(descriptor, (struct sockaddr*)&address, size) < 0) {\012    return narra_handle_failed(descriptor, narra_net_errno());\012  }\012  if (listen(descriptor, SOMAXCONN) < 0) return narra_handle_failed(descriptor, narra_net_errno());\012  return narra_handle_new(descriptor);\012}\012\012// Starts a connect. narra_io_error is EINPROGRESS while it is under way:\012// wait until the descriptor is writable, then read Handles.connected.\012static narra_handle* narra_handle_connect(lstr* host, int64_t port) {\012  narra_io_error = 0;\012  struct sockaddr_storage address;\012  socklen_t size = 0;\012  if (!narra_handle_address(host, port, &address, &size)) {\012    return narra_handle_failed(-1, NARRA_IO_BAD_ADDRESS);\012  }\012  int descriptor = narra_handle_socket(&address);\012  if (descriptor < 0) return narra_handle_new(-1);\012  if (connect(descriptor, (struct sockaddr*)&address, size) < 0) {\012    int failure = narra_net_errno();\012    // A nonblocking connect on Windows reports that it would block.\012    if (failure != EINPROGRESS && failure != EINTR && failure != EWOULDBLOCK) return narra_handle_failed(descriptor, failure);\012    narra_io_error = EINPROGRESS;\012  }\012  return narra_handle_new(descriptor);\012}\012\012// The result of a connect that was under way: 0 or its errno value.\012static int64_t narra_handle_connected(narra_handle* handle) {\012  int failure = 0;\012  socklen_t size = sizeof(failure);\012  if (getsockopt(handle->descriptor, SOL_SOCKET, SO_ERROR, (char*)&failure, &size) < 0) {\012    failure = narra_net_errno();\012  }\012#ifdef _WIN32\012  else if (failure != 0) {\012    // SO_ERROR holds a Winsock code.\012    WSASetLastError(failure);\012    failure = narra_net_errno();\012  }\012#endif\012  narra_io_error = failure;\012  return failure;\012}\012\012static narra_handle* narra_handle_accept(narra_handle* listener) {\012  narra_io_error = 0;\012  if (listener->descriptor < 0) return narra_handle_failed(-1, EBADF);\012  int descriptor = (int)accept(listener->descriptor, NULL, NULL);\012  if (descriptor < 0) return narra_handle_failed(-1, narra_net_errno());\012  int failure = narra_handle_prepare(descriptor);\012  if (failure != 0) return narra_handle_failed(descriptor, failure);\012  return narra_handle_new(descriptor);\012}\012\012// The port the socket is bound to, or -1.\012static int64_t narra_handle_local_port(narra_handle* handle) {\012  struct sockaddr_storage address;\012  socklen_t size = sizeof(address);\012  if (handle->descriptor < 0) return -1;\012  if (getsockname(handle->descriptor, (struct sockaddr*)&address, &size) < 0) return -1;\012  if (address.ss_family == AF_INET) return ntohs(((struct sockaddr_in*)&address)->sin_port);\012  if (address.ss_family == AF_INET6) return ntohs(((struct sockaddr_in6*)&address)->sin6_port);\012  return -1;\012}\012\012// One read takes at most this many bytes, whatever the caller asks for.\012#define NARRA_IO_READ_LIMIT 65536\012\012static _Thread_local char narra_io_buffer[NARRA_IO_READ_LIMIT];\012\012// Up to limit bytes, at most NARRA_IO_READ_LIMIT; empty bytes for a limit of\012// zero or less, at the end of the stream and on a failure, which\012// narra_io_error tells apart. The result holds only the bytes that came.\012static lstr* narra_handle_read(narra_handle* handle, int64_t limit) {\012  narra_io_error = 0;\012  if (limit < 1) return lstr_new(0);\012  if (limit > NARRA_IO_READ_LIMIT) limit = NARRA_IO_READ_LIMIT;\012  if (handle->descriptor < 0) {\012    narra_io_error = EBADF;\012    return lstr_new(0);\012  }\012  ssize_t count = narra_net_read(handle->descriptor, narra_io_buffer, (size_t)limit);\012  if (count < 0) {\012    narra_io_error = narra_net_errno();\012    return lstr_new(0);\012  }\012  lstr* data = lstr_new(count);\012  memcpy(data->data, narra_io_buffer, (size_t)count);\012  return data;\012}\012\012// Writes the bytes of data from offset on and gives how many went, or -1.\012// MSG_NOSIGNAL: a closed peer is an EPIPE error, not a SIGPIPE (Windows has no SIGPIPE).\012static int64_t narra_handle_write(narra_handle* handle, lstr* data, int64_t offset) {\012  narra_io_error = 0;\012  if (handle->descriptor < 0) {\012    narra_io_error = EBADF;\012    return -1;\012  }\012  if (offset < 0 || offset > data->len) offset = data->len;\012  ssize_t count = narra_net_send(handle->descriptor, data->data + offset, (size_t)(data->len - offset));\012  if (count < 0) {\012    narra_io_error = narra_net_errno();\012    return -1;\012  }\012  return count;\012}\012\012// Whether accept failed only for the connection it took, which the peer\012// dropped or the network lost (accept(2)), so the next one may work.\012static bool narra_handle_accept_again(int64_t error) {\012  if (error == ECONNABORTED) return true;\012#ifdef __linux__\012  // Linux passes on network errors of the new connection; the others are POSIX.\012  if (error == ENETDOWN || error == EPROTO || error == ENOPROTOOPT) return true;\012  if (error == EHOSTUNREACH || error == EOPNOTSUPP || error == ENETUNREACH) return true;\012#ifdef EHOSTDOWN\012  if (error == EHOSTDOWN) return true;\012#endif\012#ifdef ENONET\012  if (error == ENONET) return true;\012#endif\012#endif\012  return false;\012}\012\012// Whether a wait failed because another task waits on the socket in the same\012// direction: one reader and one writer at a time.\012static bool narra_handle_busy(int64_t error) {\012  return error == EEXIST;\012}\012\012// Whether a call failed only because it would have to wait.\012static bool narra_handle_retry(int64_t error) {\012  return error == EAGAIN || error == EWOULDBLOCK || error == EINTR;\012}\012\012static lstr* narra_handle_message(int64_t error) {\012  if (error == NARRA_IO_BAD_ADDRESS) return lstr_from_cstr(\"not a numeric IPv4 or IPv6 address and port\");\012#ifdef _WIN32\012  if (error == ECONNREFUSED) return lstr_from_cstr(\"Connection refused\");\012  if (error == ECONNRESET) return lstr_from_cstr(\"Connection reset by peer\");\012  if (error == EADDRINUSE) return lstr_from_cstr(\"Address already in use\");\012  if (error == ETIMEDOUT) return lstr_from_cstr(\"Connection timed out\");\012  if (error == ENOTCONN) return lstr_from_cstr(\"Socket is not connected\");\012  if (error == EPIPE) return lstr_from_cstr(\"Broken pipe\");\012#endif\012  return lstr_from_cstr(strerror((int)error));\012}\012\012// The errno value of the last call, 0 when it succeeded.\012static int64_t narra_handle_error(void) {\012  return narra_io_error;\012}\012\012// Whether a connect is under way.\012static bool narra_handle_pending(int64_t error) {\012  return error == EINPROGRESS;\012}\012"};
