static lstr L1456 = {0, 651, "// std/internal/terminal. Whether a stream is a terminal, and its width in columns.\012#ifndef __wasi__\012#include <sys/ioctl.h>\012#endif\012#include <unistd.h>\012\012static bool narra_terminal_is_terminal(int64_t descriptor) {\012  return isatty((int)descriptor) != 0;\012}\012\012// The columns of the terminal on the descriptor; 0 when it is not a terminal or reports no width.\012static int64_t narra_terminal_columns(int64_t descriptor) {\012#ifdef __wasi__\012  // WASI has no ioctl, so a terminal reports no width.\012  (void)descriptor;\012  return 0;\012#else\012  struct winsize size;\012  if (ioctl((int)descriptor, TIOCGWINSZ, &size) != 0) return 0;\012  return (int64_t)size.ws_col;\012#endif\012}\012"};
